"""Generate NBA_DATA_QUALITY_REPORT.md from warehouse queries + recorded audit files. Nothing is hand-typed; unknowns are labelled."""
import json
from pathlib import Path
from .. import config

ROOT = config.ROOT
DISC = ROOT / 'data' / 'discovery'


def md(headers, rows):
    return '\n'.join(['| ' + ' | '.join(map(str, headers)) + ' |', '|' + '---|' * len(headers)] + ['| ' + ' | '.join('' if c is None else str(c) for c in r) + ' |' for r in rows])


def q(con, sql, *a):
    return con.execute(sql, list(a)).fetchall()


def load(name):
    p = DISC / name
    return json.loads(p.read_text()) if p.exists() else None


def write(con, out=None):
    out = Path(out or ROOT / 'NBA_DATA_QUALITY_REPORT.md')
    seasons = [r[0] for r in q(con, "SELECT DISTINCT season FROM games WHERE season IS NOT NULL AND season_type='regular' AND in_gamelog ORDER BY 1")]
    L = ['# NBA Data Quality Report', '',
         'Generated by `python -m nba_props report` from the local warehouse (`data/warehouse/nba.duckdb`) and the audit files in `data/discovery/`. Every number below comes from a query; anything not measured is marked **NOT RUN / UNVERIFIED**. No row was imputed, synthesised or inferred to fill a gap.', '']
    runs = q(con, "SELECT run_id, command, season, status, requests, failures, started_at, finished_at FROM ingestion_runs ORDER BY started_at")
    api = q(con, "SELECT any_value(nba_api_version) FROM source_requests")[0][0]
    L += ['## 1. Scope and provenance', '', f'* `nba_api` version: **{api}**; DuckDB warehouse; raw responses content-addressed under `data/raw/` (gitignored).',
          f'* Ingestion runs recorded: {len(runs)}; requests logged: {q(con, "SELECT count(*) FROM source_requests")[0][0]:,} ({q(con, "SELECT count(*) FROM source_requests WHERE NOT ok")[0][0]} failed).',
          '* Default collection is **regular season only**. Playoffs, play-in and preseason were NOT ingested; the Cup final (`006`) and all-star games are excluded.',
          f'* Completion time of a game is not exposed by the endpoints used: a game is treated as available **{config.COMPLETION_BUFFER_H:g} h after tip-off** (assumption, `config.COMPLETION_BUFFER_H`).', '']
    # ---- coverage
    rows = []
    for s in seasons:
        g = q(con, """SELECT count(*) FILTER (WHERE in_schedule), count(*) FILTER (WHERE in_schedule AND game_status=3), count(*) FILTER (WHERE in_gamelog), min(game_date) FILTER (WHERE in_gamelog), max(game_date) FILTER (WHERE in_gamelog)
                      FROM games WHERE season=? AND season_type='regular'""", s)[0]
        pg = q(con, "SELECT count(*) FROM player_game WHERE season=?", s)[0][0]; tg = q(con, "SELECT count(*) FROM team_game WHERE season=?", s)[0][0]
        pa = q(con, "SELECT count(*) FROM player_advanced_game a JOIN games g USING(game_id) WHERE g.season=?", s)[0][0]
        ta = q(con, "SELECT count(*) FROM team_advanced_game a JOIN games g USING(game_id) WHERE g.season=?", s)[0][0]
        rows.append((s, g[0], g[1], g[2], f'{g[3]} → {g[4]}', f'{pg:,}', f'{tg:,}', f'{pa:,}', f'{ta:,}'))
    L += ['## 2. Coverage by season (regular season)', '', md(['Season', 'Games listed in schedule', 'Completed per schedule', 'Games ingested', 'Date range', 'Player-game rows', 'Team-game rows', 'Player advanced rows', 'Team advanced rows'], rows), '',
          '2026-27 is in progress: "games ingested" counts completed games only.', '']
    # ---- integrity checks
    dq = q(con, "SELECT season, check_name, severity, passed, observed, expected FROM data_quality_results ORDER BY season, severity, check_name")
    fails = [r for r in dq if not r[3]]
    L += ['## 3. Data-quality checks', '', f'{len(dq)} checks stored in `data_quality_results`; **{sum(1 for r in fails if r[2] == "error")} error-severity failures**, {sum(1 for r in fails if r[2] == "warning")} warnings, {sum(1 for r in fails if r[2] == "info")} informational deviations.', '']
    if fails:
        L += [md(['Season', 'Check', 'Severity', 'Observed', 'Expected'], [(r[0], r[1], r[2], str(r[4])[:160], str(r[5])[:60]) for r in fails]), '']
    L += ['<details><summary>All passing checks</summary>', '', md(['Season', 'Check', 'Severity', 'Observed'], [(r[0], r[1], r[2], str(r[4])[:100]) for r in dq if r[3]]), '', '</details>', '']
    # ---- 2026-27 schedule investigation
    L += ['## 4. 2026-27 schedule completeness (investigated, not inferred)', '']
    s27 = q(con, "SELECT count(*) FROM games WHERE season='2026-27' AND id_prefix='002' AND in_schedule")[0][0]
    per_team = q(con, """WITH t AS (SELECT team_id, count(*) n FROM (SELECT home_team_id team_id FROM games WHERE season='2026-27' AND id_prefix='002' UNION ALL SELECT away_team_id FROM games WHERE season='2026-27' AND id_prefix='002') WHERE team_id IS NOT NULL AND team_id <> '0' GROUP BY 1) SELECT n, count(*) FROM t GROUP BY 1""")
    unres = q(con, "SELECT count(*) FROM games WHERE season='2026-27' AND id_prefix='002' AND (home_team_id='0' OR away_team_id='0')")[0][0]
    cup = q(con, "SELECT game_sub_label, count(*) FROM games WHERE season='2026-27' AND id_prefix='002' AND game_subtype='in-season-knockout' GROUP BY 1")
    L += [f'* Regular-season ids listed: **{s27}** of 1230 expected (**{1230 - s27} absent**).', f'* Scheduled regular-season games per team (teams with resolved opponents): {per_team} (an 82-game schedule needs 82).',
          f'* Games with an unresolved (TBD, team id `0`) slot: **{unres}**, all NBA Cup knockout games: {cup}.',
          '* **Interpretation (hypothesis, UNVERIFIED):** each team lists 80 determined games; the missing two per team plausibly depend on NBA Cup results and have not been published yet. The 2025-26 listing contained all 1230 ids. The missing ids were **not** synthesised and no team record was inferred. Rest-day features for games adjacent to the unpublished slots may be overstated; they are flagged by `missing_rest_days`/low-sample columns only at season openers, so treat 2026-27 rest days as provisional.', '']
    # ---- minutes + reconciliation
    L += ['## 5. Minutes, joins and reconciliation', '']
    rc = q(con, """SELECT season, count(*) FILTER (WHERE min=0), count(*) FILTER (WHERE min_conflict), count(*) FILTER (WHERE min_sec IS NULL), count(*) FROM player_game GROUP BY 1 ORDER BY 1""")
    L += [md(['Season', 'Zero-minute rows', 'MIN vs MIN_SEC conflicts', 'Rows without MIN_SEC', 'Rows'], rc), '',
          'Player `MIN` from `LeagueGameLog` is integer-rounded (100% of rows); `min_exact` uses `MIN_SEC` when it agrees within 1 minute, otherwise falls back to `MIN` and sets `min_conflict`.', '']
    neutral = q(con, "SELECT season, count(*) FROM games WHERE season_type='regular' AND is_neutral GROUP BY 1 ORDER BY 1")
    L += [f'Neutral-site regular-season games (both teams read `@` in MATCHUP; home flag taken from the schedule): {neutral}', '']
    # ---- appearances / starters / inactives
    L += ['## 6. Starters, inactives and appearances', '']
    cov = q(con, """SELECT g.season, count(DISTINCT g.game_id) games, count(DISTINCT h.game_id) with_starters FROM games g LEFT JOIN historical_starters h USING(game_id) WHERE g.season_type='regular' AND g.in_gamelog GROUP BY 1 ORDER BY 1""")
    L += [md(['Season', 'Completed games', 'Games with V3 starters'], cov), '']
    inact = q(con, """WITH s AS (SELECT json_extract_string(params_json,'$.game_id') gid FROM source_requests WHERE endpoint='BoxScoreSummaryV3' AND ok)
                      SELECT g.season, g.game_date, count(*) requested, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM historical_inactives i WHERE i.game_id=g.game_id)) with_inactives
                      FROM games g JOIN s ON s.gid=g.game_id GROUP BY ALL ORDER BY 1,2""")
    if inact:
        tot_r, tot_i = sum(r[2] for r in inact), sum(r[3] for r in inact)
        L += [f'**Official inactives (BoxScoreSummaryV3):** {tot_i} of {tot_r} requested games returned any inactive player. Coverage by game date:', '', md(['Season', 'Game date', 'Games requested', 'With inactives'], inact), '',
              '**Finding:** inactive lists are populated for the most recent games but largely empty for older ones in the same season, so `historical_inactives` must NOT be treated as a complete historical record. A historical-coverage test across 2023-24 → 2025-26 is outstanding (the API was throttled during collection; see section 9).', '']
    else:
        L += ['**Official inactives:** no summaries ingested yet. UNVERIFIED.', '']
    ap = q(con, "SELECT status, knowledge_class, count(*) FROM player_appearances GROUP BY ALL ORDER BY 3 DESC")
    L += ['Appearance statuses (confirmed vs inferred):', '', md(['Status', 'Knowledge class', 'Rows'], ap), '',
          '`INFERRED_ABSENT` uses games on **both sides** of the target (retrospective) and is never read by any pregame feature (tested).', '']
    # ---- requests
    L += ['## 7. API requests, failures and collection duration', '']
    rq = q(con, """SELECT endpoint, count(*), count(*) FILTER (WHERE NOT ok), count(*) FILTER (WHERE attempts > 1), round(avg(duration_s),2), round(max(duration_s),1), round(sum(duration_s)/60,1) FROM source_requests GROUP BY 1 ORDER BY 2 DESC""")
    L += [md(['Endpoint', 'Requests', 'Failed', 'Needed retries', 'Mean s', 'Max s', 'Total min'], rq), '',
          md(['Run', 'Command', 'Season(s)', 'Status', 'Requests', 'Failures', 'Started (UTC)', 'Finished (UTC)'], runs), '']
    # ---- identity checks
    fc = load('formula_checks.json')
    if fc:
        rows = [(k, v['verdict'], v['n'], f"{v['mae']:.4g}", f"{v['bias']:+.3g}", f"{v['max_abs']:.3g}", v['n_exceptions']) for k, v in fc['identities'].items()]
        L += ['## 8. Formula identities against API columns (completed seasons)', '', md(['Check', 'Verdict', 'n', 'MAE', 'Bias', 'Max abs', 'Exceptions'], rows), '']
    # ---- leakage audit
    la = load('leakage_audit.json')
    L += ['## 9. Leakage and time-travel audit (real data)', '']
    if la:
        sc = la['scan']
        L += [md(['Season', 'Feature rows (all cutoffs)', 'Available-at-cutoff violations (player / team)', 'History not before target', 'Duplicate keys', 'Rows with unknown tip'],
                 [(s, f"{d['rows']:,}", f"{d.get('available_at_cutoff_violations')} / {d.get('team_available_at_cutoff_violations')}", d.get('history_game_not_before_target'), d.get('duplicate_keys'), d.get('tip_unknown_rows')) for s, d in sc.items()]), '']
        ind = la['independent']
        L += [md(['Season', 'Rows recomputed independently in pandas', 'Mismatches'], [(s, d['rows_checked'], d['mismatches']) for s, d in ind.items()]), '']
        tt = la['time_travel']
        L += [f'**Time-travel:** {len(tt)} historical days rebuilt with only earlier data vs the full database; rows compared: {sum(t["n_rows"] for t in tt):,}; **days with any differing column: {sum(1 for t in tt if t["mismatching_columns"])}**.', '',
              md(['Season', 'Date', 'Rows', 'Differing columns'], [(t['season'], t['game_date'], t['n_rows'], t['mismatching_columns']) for t in tt]), '']
        pz = la['poison']
        L += [f'**Target-day poisoning:** box scores of the target day overwritten with absurd values in a clone; features for that day unchanged in {sum(1 for p in pz if not p["mismatching_columns"])}/{len(pz)} seasons tested.', '']
        u = la['unknown_tip']
        L += [f'**Unknown tip-off times** ({u["season"]}): rows using same/previous-day history = {u["same_or_previous_day_history_rows"]}; availability violations = {u["availability_violations"]}; history games used with known tips {u["history_games_known_tip"]:,.0f} vs unknown tips {u["history_games_unknown_tip"]:,.0f} (conservative mode uses less, never more).', '']
        rr = la['roster']
        L += ['**Strictly-pregame roster eligibility** (built only from appearances available at the cutoff) versus who actually played:', '',
              md(['Season', 'Actual participants', 'Eligible pregame', 'Recall', 'Precision', 'Participants missing', 'of which never seen for the team'],
                 [(s, f"{d['actual_participants']:,}", f"{d['eligible_pregame']:,}", f"{d['recall']:.3f}", f"{d['precision']:.3f}", f"{d['participants_missing_from_pregame_roster']:,}", f"{d['of_which_never_seen_for_team_before']:,}") for s, d in rr.items()]), '',
              'Recall below 1 is expected and **not corrected**: players new to a team (trades, call-ups, rookies) cannot be known pregame from game logs alone. Precision shows how many pregame-eligible players did not play (injured/rested): that is the missing-availability problem an external injury feed would address. Training rows are currently the players who actually played, which conditions on the outcome of availability; this selection effect must be handled in any modelling.', '']
    else:
        L += ['NOT RUN (`python scripts/run_leakage_audit.py`).', '']
    # ---- feature readiness
    L += ['## 10. Feature readiness after ingestion', '']
    fr = q(con, """SELECT season, cutoff_hours, count(*), round(avg(low_sample_l5::int),3), round(avg(low_sample_l10::int),3), round(avg(low_sample_l20::int),3), round(avg(no_prior_season::int),3), round(avg(no_history_in_warehouse::int),4),
                   round(avg(missing_starter_info::int),3), round(avg(team_changed_vs_last::int),4) FROM asof_player_features GROUP BY ALL ORDER BY 1,2""") if q(con, "SELECT count(*) FROM information_schema.tables WHERE table_name='asof_player_features'")[0][0] else []
    if fr:
        L += [md(['Season', 'Cutoff h', 'Rows', 'Low-sample L5', 'L10', 'L20', 'No prior season', 'No history at all', 'Missing starter info', 'Team changed vs last'], fr), '',
              'Starter history exists only for games whose V3 box score was collected (see section 6); `missing_starter_info` is therefore high and the feature must be treated as unavailable outside covered games.', '']
    reg = json.loads((ROOT / 'nba_feature_registry.json').read_text())['features'] if (ROOT / 'nba_feature_registry.json').exists() else []
    if reg:
        from collections import Counter
        c = Counter((f['readiness'], f['implementation_status']) for f in reg)
        L += ['Registry readiness vs implementation:', '', md(['Readiness', 'Implementation', 'Features'], [(k[0], k[1], v) for k, v in sorted(c.items())]), '']
    # ---- tracking pilot
    p = ROOT / 'data' / 'processed' / 'tracking_pilot.json'
    L += ['## 11. Date-windowed tracking pilot (optional layer)', '']
    if p.exists():
        t = json.loads(p.read_text())
        L += [f"Requests ok/failed: {t['requests_ok']}/{t['requests_failed']}; exact matches: {t['exact']}; mismatches: {t['mismatch']}; empty-tracking-with-games: {t['empty_but_games']}.", '',
              md(['Season', 'Date', 'Measure', 'Verdict', 'Track rows', 'Box rows', 'Match rate', 'GP max', 'Dup ids'], [(r['season'], r['date'], r['measure'], r.get('verdict', r.get('error')), r.get('track_rows'), r.get('box_rows'), r.get('match_rate'), r.get('gp_max'), r.get('dup_player_ids')) for r in t['rows']]), '',
              f"Window semantics: {t['semantics']}", '', f"Cost estimate for a full backfill: {t['cost_estimate']}", '']
    else:
        L += ['**NOT RUN.** The stats API was unresponsive when the pilot was due (see section 12). The pilot code and its logic tests exist; nothing about historical tracking coverage beyond the single date verified during discovery (2026-01-15, Passing) is established.', '']
    L += ['## 12. Known gaps and risks', '',
          '* The stats API throttled the collector after roughly 900 requests at ~1.5 req/s (hung connections; the host answered its homepage but not `/stats/`). Pacing was lowered to 1.5 s with one worker and a circuit breaker was added. Collection is resumable; what was and was not collected is stated in sections 2 and 6.',
          '* Regular season only; no playoffs/play-in/preseason.', '* Official inactives are not a complete historical record (section 6).',
          '* 2026-27 schedule listing is incomplete (section 4).', '* Completion time is an assumption (`COMPLETION_BUFFER_H`).', '* No injury/status feed, so pregame availability for the target game is unknown beyond lagged appearances.',
          '* No forecast accuracy has been evaluated; all `forecast_accuracy` verification levels are `untested`.', '']
    out.write_text('\n'.join(L) + '\n')
    return str(out)
